 private array $review=[];
 private function safe($line): bool {
  return $line && in_array($line->pricing_status,['estimate','reference'],true) && !($line->committed_quantity??0) && !($line->paid_quantity??0) && blank($line->receipt_reference) && !CostConsultation::where('costable_type',$line::class)->where('costable_id',$line->id)->where(fn($q)=>$q->whereNotNull('sent_at')->orWhereHas('quotes'))->exists();
 }
 private function revise(BudgetLine|ActivityMaterial|null $line,array $expected,array $changes): bool {
  if(!$this->safe($line)){if($line)$this->review[]=$line->name;return false;}
  foreach($expected as $field=>$value)if($line->$field!==$value){$this->review[]=$line->name;return false;}
  $service=app(Consultations::class);$before=$service->definition($line);$draft=CostConsultation::where('costable_type',$line::class)->where('costable_id',$line->id)->first();
  $line->update($changes+['pricing_status'=>'estimate','price_checked_at'=>'2026-10-01']);
  if($draft&&!$draft->sent_at&&$draft->quotes()->doesntExist()&&$draft->body_fr===$before['body_fr']&&$draft->body_pt===$before['body_pt'])$draft->update($service->definition($line));
  return true;
 }
 private function consultation($line,string $fr='',string $pt=''): void {
  $c=app(Consultations::class)->ensure($line);
  // Preserve sent drafts and supplier replies. New specifications go in private notes.
  $note="Révision opérationnelle 01/10/2026 : ".$line->name.". Quantité : ".app(Consultations::class)->quantity($line).' '.$line->unit.".\n".$line->price_source;
  if(!str_contains($c->local_search_notes??'','Révision opérationnelle 01/10/2026'))$c->update(['local_search_notes'=>trim(($c->local_search_notes??'')."\n".$note)]);
  if($c->wasRecentlyCreated&&$fr)$c->update(['body_fr'=>$c->body_fr."\n\n".$fr,'body_pt'=>$c->body_pt."\n\n".$pt]);
 }
