 private function electrical($p,$s): void {
  $pole=SiteInfrastructure::where('event_project_id',$p->id)->where('template_key','pole-stands')->first();
  if($pole&&$pole->status==='declared'&&$pole->description==='Plusieurs départs de 4 A envisagés, non confirmés. Dimensionner le nombre, la simultanéité, la protection et la longueur de chaque ligne avec le technicien.')$pole->update(['description'=>'Départs individuels demandés 6 A, longueur maximale 50 m par stand. Coffrets six sorties à dimensionner, protections, capacité amont et phases à vérifier. Aucune capacité réseau ni simultanéité validée.']);
  foreach($s->includedStands as $stand){
   $line=$s->budgetLines()->firstOrCreate(['costing_key'=>'stand-extension-'.$stand->public_id],['name'=>'Électricité : rallonge 50 m maximum · '.$stand->name,'kind'=>'cost','scope'=>'stand','stand_id'=>$stand->id,'expense_type'=>'investment','forecast_quantity'=>1,'unit'=>'rallonge','unit_gross_cents'=>23739,'vat_basis_points'=>null,'pricing_status'=>'estimate','price_checked_at'=>'2026-10-01','price_source'=>'Comparateur AS-Schwabe 60341 H07RN-F 3G2,5 50 m : Duarte Neves affiche 193 € sans base IVA explicite dans la page consultée. Pour provision UNIQUEMENT, 193 supposés HT × 1,23 = 237,39 € ; ce n’est pas un prix TTC fournisseur vérifié. https://www.duarteneves.com/pt/extensoes-e-blocos-de-tomada/2018-neoprene-borracha-extensao-cabo-50m-h07rn-f-3g25-4011160603419.html. Demander devis global/câbles à la longueur réelle. Équipement reste à QAPAS et prestation incluse au prix du stand, aucune nouvelle recette. 6 A maximum demandés : section/protections/terre/chute de tension/cheminement à valider par technicien.']);
   $infra=SiteInfrastructure::firstOrCreate(['event_project_id'=>$p->id,'template_key'=>'extension-'.$stand->public_id],['name'=>'Liaison demandée 6 A · '.$stand->name,'kind'=>'distribution','source_id'=>$pole?->id,'status'=>'declared','budget_line_id'=>$line->id,'amp_limit'=>6,'voltage_v'=>230,'phases'=>'single','cable_marking'=>'H07RN-F 3G2,5 — référence de consultation','conductor_count'=>3,'section_mm2'=>2.5,'description'=>'Liaison 50 m maximum prévue, longueur réelle à relever. AS-Schwabe 60341 comme référence de devis ; coffret partagé six sorties et protections individuelles à définir. Aucun montage/alimentation approuvés.']);
   if(!$stand->requirements()->where('kind','electricity')->exists())StandRequirement::create(['stand_id'=>$stand->id,'name'=>'Liaison de base incluse — 6 A, 50 m maximum','kind'=>'electricity','quantity'=>1,'unit'=>'liaison','requested_amps'=>6,'line_length_m'=>50,'source_id'=>$infra->id,'budget_line_id'=>$line->id,'provided_by'=>'qapas','justification'=>'Prévision de fourniture incluse dans le prix du stand, pas de supplément automatique. Longueur maximale, pas distance mesurée. Lister appareils et puissances réelles avant validation ; 1 380 W est un plafond contractuel envisagé, pas une consommation garantie.']);
  }
 }
 private function materials($p,$s): void {
