  $definitions=collect(json_decode(file_get_contents(database_path('data/costing-materials-2026.json')),true,512,JSON_THROW_ON_ERROR))->where('activity_key','omelete-retro')->keyBy('name');
  $m=$a->materials()->where('name','Mini-rétro adaptée et contrôlée')->first();if($this->safe($m)&&$m->unit_gross_cents===9471&&$m->price_source===($definitions['Mini-rétro adaptée et contrôlée']['price_source']??null))$this->revise($m,[],['name'=>'Mini-rétro contrôlée avec pince compatible','price_source'=>$m->price_source.' Révision : aucune adaptation sur mesure demandée. Pince fermante compatible à fournir ou louer ; confirmer axes/attache, masse, hydraulique et aptitude à la manipulation délicate.']);
  $grip=$a->materials()->where('name','Support stable et dispositif de prise à valider')->first();
  if($this->safe($grip)&&$grip->unit_gross_cents===12000&&$grip->price_source===($definitions['Support stable et dispositif de prise à valider']['price_source']??null)){
   $this->revise($grip,[],['name'=>'Pince fermante / grappin compatible — option achat','quantity'=>1,'basis'=>'fixed','procurement'=>'purchase','unit'=>'accessoire','unit_gross_cents'=>27999,'vat_basis_points'=>null,'pricing_status'=>'estimate','price_source'=>'Repère fourni par le porteur : DANWIWEE B0DYMYH4FF, Amazon Belgique, 279,99 €. Page inaccessible à la vérification ; prix/IVA/port Portugal non confirmés. https://www.amazon.com.be/dp/B0DYMYH4FF. Achat facultatif à retirer si une pince compatible est comprise avec la mini-rétro. Ce descriptif de pince à bois ne prouve pas une commande hydraulique ni la compatibilité machine ou la prise d’œufs. Fournisseur doit confirmer axes/attache, ouverture, poids, hydraulique et notice. Pas d’adaptation sur mesure.']);
   $support=$a->materials()->firstOrCreate(['name'=>'Support stable de boîte — hors pince'],['quantity'=>1,'basis'=>'fixed','procurement'=>'loan','unit'=>'support','pricing_status'=>'estimate','price_source'=>'Support de boîte nécessaire distinct de la pince ; matériau, stabilité, mise à disposition et coût à préciser après répétition. Aucun prix nul ou prêt acquis présumé.']);$this->consultation($grip);$this->consultation($support);
  }
  $line=$s->budgetLines()->where('name','Engins : adaptation, assurance et encadrement technique')->first();
  if($this->safe($line)&&$line->unit_gross_cents===null&&str_starts_with($line->price_source??'','Hypothèse interne, non devis, 30/09/2026.'))$this->revise($line,[],['name'=>'Engins : supervision, contrôle et éventuel complément de couverture','price_source'=>'Aucune transformation sur mesure budgétée. Confirmer encadrement, vérification de la pince/machine et couverture des jeux. Assurance événement 50 € dans son poste séparé ; ne prévoir ici qu’un complément explicitement exclu. Opérateur d’équipe ≠ supervision ou couverture confirmée.']);
 }
